import React, { useState } from 'react';
import ResetPasswordModal from './ResetPasswordModal';

export default function TeacherDashboard({ userName, subject, handleLogout }) {
  const [showResetModal, setShowResetModal] = useState(false);
  const [activeTab, setActiveTab] = useState('dashboard');
  const teacherSubject = subject || 'ICT';

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return (
          <>
            <div style={{ backgroundColor: '#15803d', padding: '30px', borderRadius: '15px', color: 'white', marginBottom: '30px' }}>
              <h1 style={{ margin: '0 0 10px 0', fontSize: '32px' }}>Welcome, {userName}! 👋</h1>
              <p style={{ margin: 0, opacity: 0.9 }}>Content Management System (CMS) is active. Manage your lessons and activities below.</p>
            </div>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '20px', marginBottom: '40px' }}>
              <DashboardCard title="Active Subject" count={teacherSubject} icon="📚" color="#eff6ff" textColor="#1d4ed8" />
              <DashboardCard title="Uploaded Lessons" count="12" icon="📺" color="#f0fdf4" textColor="#15803d" />
              <DashboardCard title="Active Quizzes" count="05" icon="📝" color="#fefce8" textColor="#a16207" />
            </div>
          </>
        );

      case 'upload':
        // 🟢 YouTube URLs සහ PDF Upload කරන තැන (From SRS)
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <h2 style={{ color: '#1e293b', marginBottom: '20px' }}>📤 Upload Lesson Materials</h2>
            <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.05)', maxWidth: '600px' }}>
                <form style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
                    <div>
                        <label style={labelStyle}>Lesson Title</label>
                        <input type="text" placeholder="e.g. Introduction to Programming" style={inputStyle} />
                    </div>
                    <div>
                        <label style={labelStyle}>Grade Category</label>
                        <select style={inputStyle}>
                            <option>Grade 9</option>
                            <option>Grade 10</option>
                            <option>Grade 11</option>
                        </select>
                    </div>
                    <div>
                        <label style={labelStyle}>YouTube Video URL</label>
                        <input type="url" placeholder="https://youtube.com/watch?v=..." style={inputStyle} />
                    </div>
                    <div>
                        <label style={labelStyle}>PDF Handout Upload</label>
                        <input type="file" accept=".pdf" style={{...inputStyle, padding: '9px'}} />
                    </div>
                    <button type="button" style={{ padding: '12px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', marginTop: '10px' }}>+ Publish Lesson</button>
                </form>
            </div>
          </div>
        );

      case 'activities':
        // 🟢 Interactive Activities හදන තැන
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <h2 style={{ color: '#1e293b', marginBottom: '20px' }}>🎮 Manage Interactive Activities</h2>
            <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.05)' }}>
                <h3 style={{ marginTop: 0 }}>Create New Assessment</h3>
                <div style={{ display: 'flex', gap: '15px', marginTop: '15px' }}>
                    <button style={actionBtnStyle}>+ Create MCQ Quiz</button>
                    <button style={actionBtnStyle}>+ Create Matching Game</button>
                    <button style={actionBtnStyle}>+ Create Fill-in-the-blanks</button>
                </div>
            </div>
          </div>
        );

      default: return null;
    }
  };

  return (
    <div style={{ display: 'flex', minHeight: '100vh', backgroundColor: '#f4f7f6', fontFamily: 'sans-serif' }}>
      <div style={{ width: '260px', backgroundColor: '#145c2e', color: 'white', padding: '25px 0', display: 'flex', flexDirection: 'column' }}>
        <div style={{ padding: '0 25px', marginBottom: '40px', textAlign: 'center' }}>
            <h2 style={{ margin: 0, fontSize: '22px' }}>Aura Pen Saku</h2>
            <p style={{ margin: '5px 0 0 0', fontSize: '12px', color: '#bbf7d0' }}>Teacher CMS</p>
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', padding: '0 15px' }}>
          <SidebarBtn active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon="🏠" text="Dashboard" />
          <SidebarBtn active={activeTab === 'upload'} onClick={() => setActiveTab('upload')} icon="📤" text="Content Manager" />
          <SidebarBtn active={activeTab === 'activities'} onClick={() => setActiveTab('activities')} icon="🎮" text="Manage Activities" />
          <SidebarBtn active={false} onClick={() => setShowResetModal(true)} icon="🔑" text="Change Password" />
        </div>
        <div style={{ marginTop: 'auto', padding: '0 15px' }}><button onClick={handleLogout} style={logoutBtnStyle}>Logout</button></div>
      </div>
      <div style={{ flex: 1, padding: '40px 50px' }}>{renderContent()}</div>
      {showResetModal && <ResetPasswordModal userName={userName} role="teacher" setShowResetModal={setShowResetModal} />}
    </div>
  );
}

const SidebarBtn = ({ active, onClick, icon, text }) => (<button onClick={onClick} style={{ width: '100%', textAlign: 'left', padding: '14px 20px', backgroundColor: active ? 'rgba(255,255,255,0.15)' : 'transparent', color: 'white', border: 'none', borderRadius: '10px', cursor: 'pointer', fontSize: '15px', display: 'flex', alignItems: 'center', gap: '12px', fontWeight: active ? 'bold' : 'normal' }}><span style={{ fontSize: '18px' }}>{icon}</span> {text}</button>);
const DashboardCard = ({ title, count, icon, color, textColor }) => (<div style={{ backgroundColor: 'white', padding: '25px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', display: 'flex', alignItems: 'center', justifyContent: 'space-between', borderLeft: `5px solid ${textColor}` }}><div><p style={{ margin: '0 0 5px 0', color: '#64748b', fontSize: '14px', fontWeight: 'bold' }}>{title}</p><h2 style={{ margin: 0, color: '#1e293b', fontSize: '28px' }}>{count}</h2></div><div style={{ width: '60px', height: '60px', borderRadius: '50%', backgroundColor: color, display: 'flex', justifyContent: 'center', alignItems: 'center', fontSize: '28px' }}>{icon}</div></div>);
const labelStyle = { display: 'block', marginBottom: '8px', color: '#475569', fontSize: '14px', fontWeight: 'bold' };
const inputStyle = { width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', outline: 'none', boxSizing: 'border-box', color: '#1e293b' };
const actionBtnStyle = { flex: 1, padding: '12px', backgroundColor: '#f0fdf4', color: '#15803d', border: '1px solid #bbf7d0', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer' };
const logoutBtnStyle = { width: '100%', padding: '12px', backgroundColor: '#ef4444', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer' };
